-- sort_order 101: AIと労働の未来  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'AIと労働の未来', E'人工知能の急速な発展は、労働市場に根本的な変革をもたらしつつある。従来、機械化の波は主として肉体労働を代替してきたが、現在のAI技術は知的労働の領域にまで浸透し、会計士・弁護士・医師など高度な専門職でさえその影響を免れない状況となっている。\nこうした変化に対し、楽観論者は「AIが単純作業を肩代わりすることで、人間はより創造的な仕事に集中できる」と主張する。一方、悲観論者は「技術革新の速度が人間の適応能力を上回り、大規模な失業が生じる」と警告する。いずれの見方も一面の真理を含んでいるが、問題の核心は雇用の総量ではなく、その分配にある。\nAIが生み出す経済的恩恵が一部の資本家や技術者に集中する一方、雇用を失った労働者が新たな職を見つけられない場合、社会的格差は深刻化する。そのため、リスキリング（技術再習得）への公的投資や、ユニバーサル・ベーシック・インカムの導入など、制度的な対応が急務とされている。技術の進歩それ自体は中立的であり、問題はそれをいかに社会全体の利益に資するよう設計するかにある。', 'article', 'N1', 510, '[]'::jsonb, '{"question":"本文の内容と合うものはどれか。","options":["AIは肉体労働のみを代替し、知的労働への影響は限定的である。","楽観論者はAIが大規模失業をもたらすと警告している。","筆者はAIによる雇用問題の核心は雇用の総量ではなく分配にあると述べている。","技術の進歩は本質的に社会に有害であると筆者は主張している。"],"answer":2}'::jsonb, 101
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='AIと労働の未来');

-- sort_order 102: 少子高齢化と社会保障  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '少子高齢化と社会保障', E'日本が直面する少子高齢化の問題は、単なる人口動態の変化にとどまらず、社会保障制度の持続可能性に深刻な疑問を投げかけている。現行の年金制度は、現役世代が高齢者を支える「賦課方式」を基本としているため、現役人口の減少と受給者の増加が同時に進む現状では、制度の根幹が揺らぎかねない。\n厚生労働省の推計によれば、2050年には65歳以上の人口が総人口の約40パーセントに達するとされ、1人の高齢者を1.3人の現役世代が支える計算となる。これは現在の水準と比較して著しく負担が増大することを意味する。\nこの課題への対応として、政府は定年延長・女性活躍推進・外国人労働者の受け入れ拡大など、労働供給を増やす施策を打ち出しているが、いずれも本質的な解決策とはなっていない。根本的な解決には出生率の回復が不可欠であるが、それには住居費・教育費の高騰や長時間労働文化など、多岐にわたる構造的問題の解消が前提となる。少子化対策は単一の政策で解決できる問題ではなく、社会全体の価値観の転換を伴う長期的取り組みが求められる。', 'article', 'N1', 490, '[]'::jsonb, '{"question":"本文で述べられている少子高齢化への政府の対応として正しいものはどれか。","options":["定年延長や女性活躍推進など労働供給を増やす施策を打ち出しているが、根本的解決にはなっていない。","出生率の回復を最優先課題として、育児支援に集中投資している。","外国人労働者の受け入れを大幅に制限することで、雇用の安定を図っている。","年金制度を積立方式に全面移行することで財政の健全化を目指している。"],"answer":0}'::jsonb, 102
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='少子高齢化と社会保障');

-- sort_order 103: 気候変動と農業への影響  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '気候変動と農業への影響', E'地球温暖化に伴う気候変動は、世界の農業生産に甚大な影響を及ぼしつつある。気温の上昇・降水パターンの変化・極端な気象現象の頻発は、作物の収量や品質を不安定にし、食料安全保障を脅かしている。特に熱帯・亜熱帯地域の途上国では、主食作物の収量が大幅に低下するリスクが高く、既存の脆弱性がさらに増幅される恐れがある。\n一方で、温暖化が一部の高緯度地域に恩恵をもたらす側面もある。シベリアや北カナダでは農地が拡大し、小麦などの生産が増加する可能性がある。しかしこうした利益は、熱帯・亜熱帯での損失を補うには到底及ばないとされる。\n農業セクターにおける気候変動適応策として、耐熱・耐乾性品種の開発、精密農業技術の導入、灌漑システムの効率化などが進められている。また、農業自体が温室効果ガスの排出源でもあるため、有機農業の普及や農地土壌への炭素貯留促進など、緩和策との統合的アプローチが求められている。気候変動と農業の問題は、技術的対応だけでなく、国際的な食料政策の再設計という政治的課題と不可分である。', 'article', 'N1', 495, '[]'::jsonb, '{"question":"本文における気候変動の農業への影響として正しいのはどれか。","options":["高緯度地域の農業利益が熱帯地域の損失を十分に補うとされている。","温暖化はすべての地域で農業生産に損害を与えている。","農業は温室効果ガスを吸収する役割のみを担っている。","高緯度地域では農地拡大の可能性があるが、熱帯での損失を補うには及ばないとされている。"],"answer":3}'::jsonb, 103
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='気候変動と農業への影響');

-- sort_order 104: デジタル化と個人情報  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'デジタル化と個人情報', E'デジタル技術の急速な普及に伴い、個人情報の保護をめぐる議論が世界的に高まっている。スマートフォン・SNS・IoT機器などが日常に深く浸透した現代社会では、私たちの行動・嗜好・人間関係・健康状態に至るあらゆる情報が収集・蓄積・分析される状況にある。\nこうしたデータの活用は、パーソナライズされたサービスや医療の進歩をもたらす一方、プライバシーの侵害・差別的な意思決定への悪用・国家による監視強化といったリスクを孕んでいる。欧州では「GDPR（一般データ保護規則）」が施行され、データ主体の権利保護が強化されたが、日本の個人情報保護法はその対応において後れをとっていると批判されることも多い。\n特に問題となるのが、利用者が同意の内容を十分理解しないまま個人情報の利用に同意させられる「インフォームドコンセントの形骸化」である。同意書が膨大な文字数で記述され、実質的に読まれないまま承認されるという現状は、自律的なデータ管理という理念とは程遠い。デジタル社会における個人の尊厳を守るためには、わかりやすい情報開示の義務化と、データリテラシー教育の普及が不可欠である。', 'essay', 'N1', 505, '[]'::jsonb, '{"question":"筆者が「インフォームドコンセントの形骸化」として問題視しているのはどれか。","options":["企業が個人データを第三者に無断で販売していること。","利用者が同意内容を十分理解しないまま個人情報利用に同意させられること。","国家機関が市民の通信を無断で傍受していること。","データリテラシー教育が普及していないこと。"],"answer":1}'::jsonb, 104
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='デジタル化と個人情報');

-- sort_order 105: 日本の伝統工芸の継承  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '日本の伝統工芸の継承', E'日本の伝統工芸は、長い歴史の中で培われてきた高度な技術と美的感覚の結晶であり、各地の風土や文化と深く結びついている。しかし近年、職人の高齢化と後継者不足により、多くの伝統技術が存続の危機に瀕している。経済産業省が指定する「伝統的工芸品」の産地においても、従事者数が数十年で半減した品目が少なくない。\n伝統工芸の衰退を招いた要因としては、大量生産品との価格競争・ライフスタイルの変化・修行期間の長さに見合う収入が得られない現実などが挙げられる。若い人材がこの分野に参入しにくい構造的問題は根深い。\n一方、伝統工芸の新たな可能性を模索する動きも生まれている。デザイナーや海外ブランドとのコラボレーション、ECプラットフォームを通じた海外販売、ワークショップによる体験型観光との融合など、伝統と現代をつなぐ試みが各地で展開されている。重要なのは、技術の「純粋な保存」と「現代的応用」のバランスをいかに取るかという問いである。変化を拒むことが技術の死を招き、変化しすぎることが伝統の本質を失わせるという矛盾の中で、職人たちは苦悩しながら道を探っている。', 'essay', 'N1', 500, '[]'::jsonb, '{"question":"本文が述べる伝統工芸衰退の要因として挙げられていないものはどれか。","options":["大量生産品との価格競争","ライフスタイルの変化","若い職人の海外流出","修行期間の長さに見合わない収入"],"answer":2}'::jsonb, 105
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='日本の伝統工芸の継承');

-- sort_order 106: 再生可能エネルギーの課題  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '再生可能エネルギーの課題', E'再生可能エネルギーの導入拡大は、脱炭素社会の実現に向けた最重要課題の一つとして位置づけられている。太陽光・風力・水力・地熱など多様なエネルギー源の活用が進む中、技術コストの大幅な低下が導入を後押ししている。特に太陽光発電は、過去十年間で設置コストが約90パーセント削減され、多くの地域で既存の化石燃料発電と競争できる水準に達した。\nしかし再生可能エネルギーの普及には依然として克服すべき課題が多い。最大の課題は「間欠性」の問題である。太陽光は夜間や曇天時に発電できず、風力は無風時に機能しない。これを補うためには大容量の蓄電池システムや、地域間を結ぶ送電網の整備が不可欠だが、いずれも莫大なインフラ投資を必要とする。\nまた、大規模な太陽光・風力発電施設の建設は、自然景観の破壊や生態系への影響をもたらすことがあり、地域住民との合意形成が難航する事例も多い。再生可能エネルギーはゼロカーボンの解決策として期待される一方、その導入過程における社会的・環境的コストを軽視することはできない。技術革新と政策的支援の両輪が揃って初めて、持続可能なエネルギー転換が実現する。', 'article', 'N1', 505, '[]'::jsonb, '{"question":"本文が述べる再生可能エネルギーの最大の課題はどれか。","options":["太陽光や風力が天候条件に依存する間欠性の問題","化石燃料業界からの政治的抵抗","技術者不足による導入の遅れ","設置コストが化石燃料より依然として高い点"],"answer":0}'::jsonb, 106
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='再生可能エネルギーの課題');

-- sort_order 107: グローバル化と文化的アイデンティティ  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'グローバル化と文化的アイデンティティ', E'経済のグローバル化は、物・資本・情報の国境を越えた流通を飛躍的に高め、世界の相互依存関係を深化させた。その結果、各国の消費文化・娯楽・ライフスタイルが均質化し、世界各地で同じファストフードを食べ、同じ映画を見るという状況が生まれている。\nこうした文化の均質化に対する反動として、各地でローカルな文化的アイデンティティへの回帰が見られる。地域の言語・伝統・芸術を再評価し、グローバル文化の浸透に抵抗する動きは、単なるノスタルジーではなく、コミュニティの連帯感と自尊心を保つための積極的な選択として理解すべきである。\nただし文化的アイデンティティの強調が排他主義や自文化中心主義に転化する危険性も看過できない。「文化の純粋性」を主張する言説は、しばしばマイノリティや移民の排除を正当化するために用いられてきた歴史がある。真に豊かな文化とは、外来の要素を取り込みながら変容し続けるものであり、固定的な「本物」を追求することは文化の活力を損なう可能性がある。グローバル化時代における文化的アイデンティティとは、開かれた対話の中で絶えず再構築されるべきものである。', 'essay', 'N1', 495, '[]'::jsonb, '{"question":"筆者のグローバル化と文化的アイデンティティに関する主張として最も適切なものはどれか。","options":["グローバル化は文化を均質化するため、各国は伝統文化を厳格に保護すべきだ。","文化の純粋性を守ることが豊かな文化の維持につながる。","グローバル化への抵抗はノスタルジーに過ぎず、意味がない。","文化的アイデンティティは開かれた対話の中で絶えず再構築されるべきものだ。"],"answer":3}'::jsonb, 107
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='グローバル化と文化的アイデンティティ');

-- sort_order 108: ビッグデータと医療革新  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'ビッグデータと医療革新', E'膨大な量の医療データをAIで解析するビッグデータ医療が、診断・治療・予防の各段階に革命的な変化をもたらしつつある。電子カルテ・遺伝子情報・ウェアラブルデバイスから得られる生体データを統合的に分析することで、従来の医師の経験と勘に依存していた診断プロセスが、データに基づく客観的判断へと移行しつつある。\nがん診断の分野では、AI画像解析が放射線科医を上回る精度で腫瘍を検出した事例も報告されており、早期発見率の向上が期待されている。また、個人の遺伝的特性や生活習慣データに基づいた「精密医療（プレシジョン・メディシン）」により、画一的な治療から個別最適化された治療への移行が進んでいる。\n一方で、医療ビッグデータの活用には倫理的・法的課題が伴う。患者データの収集・管理・商業利用に関する透明性の確保、アルゴリズムの偏りによる医療格差の拡大リスク、データ漏洩への対策など、解決すべき問題は多い。技術的な可能性を最大限に引き出しながら、患者の権利と公正性を守る制度設計が医療ビッグデータ時代の核心的課題である。', 'article', 'N1', 500, '[]'::jsonb, '{"question":"本文におけるビッグデータ医療の課題として挙げられていないものはどれか。","options":["医師の雇用が大幅に失われるリスク","患者データの収集・管理に関する透明性の確保","アルゴリズムの偏りによる医療格差の拡大リスク","データ漏洩への対策"],"answer":0}'::jsonb, 108
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='ビッグデータと医療革新');

-- sort_order 109: 都市集中と地方の衰退  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '都市集中と地方の衰退', E'日本では戦後の高度経済成長期以来、人口と経済機能の東京圏への一極集中が続いている。現在、東京圏には全国人口の約30パーセントが集積しており、政治・経済・文化・情報の中枢機能が集中する構造は依然として強固である。\nこの集中の対極として、地方では人口流出・産業空洞化・財政悪化という「地方消滅」の危機が現実のものとなりつつある。過疎化が進む地域では、公共交通の廃止・病院や学校の統廃合・空き家の急増といった生活基盤の崩壊が進んでいる。2014年に発表された「消滅可能性都市」リストは、全国896自治体が将来消滅する可能性があると指摘し、社会に衝撃を与えた。\n地方創生政策は2015年から推進されているが、移住促進・特産品開発・観光誘致といった施策は局所的な効果にとどまり、根本的な流れを変えるには至っていない。テレワークの普及により地方移住への関心が高まったという側面はあるものの、教育環境・医療・娯楽の充実度における都市との格差が、移住の最大の障壁となっている。地方再生には、インフラ整備への長期的投資と、地方での起業・イノベーションを促す生態系の構築が不可欠である。', 'article', 'N1', 510, '[]'::jsonb, '{"question":"本文が述べる「消滅可能性都市」リストについて正しいのはどれか。","options":["2015年に発表され、全国500自治体が対象とされた。","テレワーク普及後に改定され、消滅リスクが低下したと報告された。","2014年に発表され、全国896自治体が将来消滅する可能性があると指摘した。","地方創生政策の成果として2014年に廃止が発表された。"],"answer":2}'::jsonb, 109
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='都市集中と地方の衰退');

-- sort_order 110: 認知バイアスと意思決定  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '認知バイアスと意思決定', E'人間の思考は、合理的な計算機のように機能するわけではない。認知心理学の研究は、私たちの判断がさまざまな認知バイアスによって系統的に歪められることを明らかにしている。ノーベル経済学賞受賞者ダニエル・カーネマンが提唱した「システム1（直感的思考）」と「システム2（分析的思考）」の枠組みは、こうしたバイアスのメカニズムを理解する上で有効な概念モデルを提供している。\n代表的な認知バイアスとして、確証バイアス（自分の信念を支持する情報のみを重視する傾向）、アンカリング効果（最初に提示された情報に引きずられる傾向）、損失回避（同じ大きさの利益より損失を強く感じる傾向）などが挙げられる。これらのバイアスは進化的な適応の産物として形成されたものであり、日常的な状況では有用に機能することも多い。しかし複雑な判断・投資・政策立案などの場面では重大な誤りをもたらしかねない。\nバイアスへの対処として、「ナッジ」と呼ばれる行動経済学的アプローチが注目されている。選択肢の提示方法・デフォルト設定の変更・フィードバックの工夫などによって、人々をより良い意思決定へと穏やかに誘導するこの手法は、政策立案から企業のUX設計まで広く応用されている。', 'article', 'N1', 490, '[]'::jsonb, '{"question":"本文で述べられている「ナッジ」とは何か。","options":["認知バイアスを科学的に研究する心理学の一分野","選択肢の提示方法などを工夫して人々をより良い意思決定へ誘導する手法","システム2の分析的思考を強化するための教育プログラム","損失回避バイアスを克服するためのトレーニング法"],"answer":1}'::jsonb, 110
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='認知バイアスと意思決定');

-- sort_order 111: 宇宙開発の現状と展望  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '宇宙開発の現状と展望', E'21世紀の宇宙開発は、国家主導から民間主導へという構造的転換期を迎えている。スペースX・ブルーオリジン・ヴァージン・ギャラクティックなどの民間企業が再利用可能ロケットの実用化や有人宇宙飛行サービスの商業化を進め、打ち上げコストの劇的な低下をもたらした。これにより、かつては一部の超大国にのみ開かれていた宇宙空間が、より多くの国家・企業・研究機関に開かれるようになりつつある。\n現在の宇宙開発の焦点は、月・火星への有人探査と、地球低軌道の商業利用に集約される。NASAのアルテミス計画は2020年代中盤までに人類を再び月面に送ることを目指しており、中国・欧州・インドなども月・火星探査プログラムを積極的に推進している。\n一方で、宇宙開発の急速な展開は新たな問題を生み出している。衛星の大量打ち上げによるスペースデブリ（宇宙ゴミ）の増加は、将来の宇宙利用を脅かすケスラー症候群のリスクを高めている。また、宇宙資源の採掘権をめぐる国際法の整備が追いつかず、宇宙をめぐる覇権争いが激化する懸念もある。宇宙の持続可能な利用に向けた国際ガバナンスの枠組み構築が急務とされている。', 'article', 'N1', 505, '[]'::jsonb, '{"question":"本文で述べられているスペースデブリの問題として正しいのはどれか。","options":["スペースデブリは主に月面探査によって生じると述べられている。","スペースデブリの除去技術はすでに実用化されており、問題は解決されつつある。","スペースデブリは民間企業ではなく国家機関のみが対処する責任を持つ。","衛星の大量打ち上げによるスペースデブリ増加が将来の宇宙利用を脅かすリスクがある。"],"answer":3}'::jsonb, 111
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='宇宙開発の現状と展望');

-- sort_order 112: 食料安全保障の危機  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '食料安全保障の危機', E'食料安全保障とは、すべての人が常に活動的で健康な生活を営むための十分な食料を、物理的・経済的に確保できる状態を指す。しかし現実には、世界人口の約10パーセントに相当する8億人以上が慢性的な飢餓状態にあり、一方で先進国では大量の食料が廃棄されるという矛盾した状況が存在する。\n食料安全保障を脅かす要因は複合的である。気候変動による農業生産の不安定化、水資源の枯渇、農地の塩害・砂漠化、人口増加による需要拡大、サプライチェーンの脆弱性、そして政治的紛争による食料支援の途絶がその主たるものとして挙げられる。2022年のウクライナ紛争は、同地域が「欧州のパンかご」と呼ばれるほどの小麦主要産地であることから、世界の穀物市場に深刻な影響を与えた。\n食料安全保障の強化には、農業生産性の向上・食料廃棄の削減・フードシステムの多元化・農業技術の途上国への移転などが不可欠である。加えて、代替タンパク質（昆虫食・培養肉・植物性肉）の普及が、従来型畜産業の環境負荷を軽減しながら食料供給を多様化する手段として期待されている。', 'article', 'N1', 495, '[]'::jsonb, '{"question":"2022年のウクライナ紛争が食料安全保障に影響を与えた理由として本文に述べられているのはどれか。","options":["ウクライナが欧州の主要な小麦産地であったため","ウクライナが世界最大の農業援助国であったため","ウクライナへの経済制裁が世界の貿易を停滞させたため","ウクライナが世界の主要な水産物輸出国であったため"],"answer":0}'::jsonb, 112
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='食料安全保障の危機');

-- sort_order 113: SNSと若者のメンタルヘルス  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'SNSと若者のメンタルヘルス', E'スマートフォンの普及とSNSの台頭は、若者のコミュニケーション様式を根本から変えた。常時接続が可能な環境の中で、青少年は一日に数時間をSNS上での情報収集・自己表現・他者との交流に費やしている。こうした変化はコミュニティの形成や情報共有に利点をもたらす一方、深刻なメンタルヘルスへの影響も指摘されている。\n複数の研究が、SNSの長時間使用と抑うつ症状・不安障害・睡眠障害の相関関係を示している。特に問題とされるのが、他者の「完璧な日常」を見せる投稿との比較による自己肯定感の低下、いいね数やフォロワー数という数値化された承認への依存、そしてサイバーいじめの深刻化である。\nただし、SNSとメンタルヘルスの関係は単純な因果関係ではなく、使用の仕方・目的・個人の心理的特性によって大きく左右される。受動的に他者の投稿を閲覧するだけの使用と、能動的に表現や交流を行う使用では、精神的影響が異なるという研究もある。重要なのは、デジタル機器との適切な距離感を持つ「デジタルウェルネス」の実践であり、教育機関や家庭が協力してメディアリテラシーを育む環境づくりが求められる。', 'article', 'N1', 505, '[]'::jsonb, '{"question":"本文でSNSと若者のメンタルヘルスの関係について述べられていることとして正しいのはどれか。","options":["SNSの使用はすべての若者に等しくメンタルヘルスへの悪影響を与える。","受動的な閲覧より能動的な交流のほうがメンタルヘルスへの悪影響が大きい。","SNSとメンタルヘルスの関係は単純な因果関係ではなく、使用の仕方や個人特性によって異なる。","SNS上でのいじめは現実社会のいじめより影響が小さいとされている。"],"answer":2}'::jsonb, 113
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='SNSと若者のメンタルヘルス');

-- sort_order 114: 量子コンピュータの可能性  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '量子コンピュータの可能性', E'量子コンピュータは、量子力学の原理を利用して情報処理を行う次世代の計算機であり、従来の古典コンピュータでは事実上不可能だった問題を解ける可能性として注目されている。古典コンピュータが「ビット（0または1）」を基本単位とするのに対し、量子コンピュータは「量子ビット（キュービット）」を使用する。キュービットは量子重ね合わせの原理により0と1を同時に保持できるため、膨大な計算を並列処理できる。\n量子コンピュータが特に威力を発揮すると期待される分野は、新薬・新素材の分子シミュレーション、暗号解読・量子暗号通信、金融ポートフォリオの最適化、物流・サプライチェーンの効率化などである。特に創薬分野では、量子シミュレーションにより従来数十年を要した新薬開発プロセスが劇的に短縮される可能性がある。\nただし現状の量子コンピュータは「ノイズの多い中規模量子（NISQ）」段階にあり、エラー率の高さと動作に必要な極低温環境の維持コストが実用化の障壁となっている。汎用的な「フォールトトレラント量子コンピュータ」の実現には、まだ数十年を要するとの見方もあり、現時点では特定の問題に特化した量子アルゴリズムの開発が研究の主軸となっている。', 'article', 'N1', 505, '[]'::jsonb, '{"question":"本文で述べられている現状の量子コンピュータの問題点はどれか。","options":["エラー率の高さと極低温環境の維持コストが実用化の障壁となっている。","計算速度が古典コンピュータより遅く、実用的な優位性がない。","量子コンピュータを操作できる技術者が世界的に不足している。","キュービット数が少なすぎて量子重ね合わせを利用できない。"],"answer":0}'::jsonb, 114
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='量子コンピュータの可能性');

-- sort_order 115: 海洋プラスチック汚染  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '海洋プラスチック汚染', E'海洋プラスチック汚染は、現代の環境問題の中でも特に可視化されやすい問題の一つであり、海鳥の消化器官に蓄積されたプラスチック片や、太平洋に漂う巨大なゴミのベルトの映像は国際的な関心を喚起してきた。毎年800万トン以上のプラスチックが海洋に流入していると推計されており、現在の傾向が続けば2050年には海中のプラスチック総量が魚の総重量を上回るとの試算もある。\n特に深刻なのがマイクロプラスチックの問題である。プラスチックが紫外線や波の力で微細化したマイクロプラスチックは、魚介類に取り込まれ食物連鎖を通じて人体にも蓄積される可能性があり、健康への長期的影響が懸念されている。最近の研究では、人間の血液・胎盤・肺からもマイクロプラスチックが検出されており、問題の深刻さが改めて認識されている。\n対策としては、プラスチックの生産規制・代替素材の開発・廃棄物管理の改善・海洋ごみの回収活動などが進められている。2022年の国連環境総会では、拘束力のある国際プラスチック条約の策定に向けた交渉開始が合意された。しかし規制が実効性を持つためには、プラスチックに大きく依存する産業構造と消費行動の転換が不可欠である。', 'article', 'N1', 505, '[]'::jsonb, '{"question":"本文でマイクロプラスチックの問題として述べられていることはどれか。","options":["マイクロプラスチックは可視化が容易であり、早期発見・対処が可能である。","マイクロプラスチックは魚介類には取り込まれるが、人体への蓄積は確認されていない。","マイクロプラスチックの除去技術がすでに開発され、問題は解決に向かっている。","マイクロプラスチックが魚介類や人体に蓄積され、健康への長期的影響が懸念されている。"],"answer":3}'::jsonb, 115
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='海洋プラスチック汚染');

-- sort_order 116: 働き方改革の実態  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '働き方改革の実態', E'2018年に施行された働き方改革関連法は、長時間労働の是正・同一労働同一賃金の実現・多様な働き方の推進を三本柱として、日本の労働慣行の抜本的な見直しを目指すものであった。時間外労働の上限規制（月45時間・年360時間）の法定化は、「過労死」という国際語にもなった日本の長時間労働文化に対する制度的な歯止めとして評価されている。\nしかし施行から数年が経過した現在も、改革の実効性については懐疑的な見方が少なくない。残業時間の削減は数字の上では進んだものの、仕事量は変わらないまま「サービス残業（不払い残業）」が増加したり、テレワーク下での「見えない長時間労働」が深刻化したりするケースが報告されている。特に中小企業においては、人手不足や業務量の問題から上限規制の遵守が困難な状況が続いている。\n同一労働同一賃金についても、正規・非正規雇用間の待遇格差の是正は緒についたばかりであり、職務給（ジョブ型雇用）への移行なしに真の均等待遇を実現することは困難との指摘がある。働き方改革の「量（時間）」から「質（生産性・やりがい）」への転換が、今後の真の課題として浮上している。', 'essay', 'N1', 505, '[]'::jsonb, '{"question":"本文が述べる働き方改革の問題点として挙げられていないものはどれか。","options":["残業時間は減ったが仕事量が変わらずサービス残業が増加するケース","女性労働者の育児休業取得率の低さ","テレワーク下での見えない長時間労働の深刻化","中小企業における上限規制の遵守の困難さ"],"answer":1}'::jsonb, 116
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='働き方改革の実態');

-- sort_order 117: バイオテクノロジーと倫理  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'バイオテクノロジーと倫理', E'ゲノム編集技術「クリスパー・キャス9（CRISPR-Cas9）」の登場は、生命科学に革命的な変化をもたらした。これまでは困難とされた遺伝子の精密な切断・改変を低コストかつ高効率で実現するこの技術は、遺伝性疾患の治療・農業品種改良・感染症対策など広範な分野での応用が期待されている。\nしかしゲノム編集技術は、その強力さゆえに深刻な倫理的問題を孕んでいる。2018年に中国の研究者が受精卵のゲノムを編集してHIV耐性を持つ双子を誕生させたことが発覚し、科学界・倫理学界に激震が走った。生殖細胞や受精卵への遺伝子改変は、改変された遺伝情報が次世代に継承される「生殖系列編集」であり、予期しない影響が将来世代に及ぶ可能性から、多くの国で法的に規制されている。\nまた「デザイナーベビー」への懸念も根強い。疾患治療の目的を超えて、外見・知能・運動能力などの「望ましい形質」を人為的に選択する可能性は、優生学の復活や社会的不平等の生物学的固定化という悪夢を呼び起こす。技術的可能性と倫理的許容性の境界を社会としていかに画定するか、科学者・倫理学者・政策立案者・市民が協議する開かれた場が必要とされている。', 'essay', 'N1', 510, '[]'::jsonb, '{"question":"2018年に中国で起きた出来事として本文に述べられているのはどれか。","options":["クリスパー技術を用いた初の農業品種改良が成功した。","ゲノム編集を禁じる初の国際条約が署名された。","研究者が受精卵のゲノムを編集してHIV耐性を持つ双子を誕生させた。","デザイナーベビーに関する国際倫理委員会が設立された。"],"answer":2}'::jsonb, 117
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='バイオテクノロジーと倫理');

-- sort_order 118: 移民政策と社会統合  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '移民政策と社会統合', E'少子高齢化が加速する先進国では、労働力不足の解消と経済活力の維持を目的として移民の受け入れ拡大が政策的選択肢として浮上している。日本においても2019年の入管法改正により特定技能制度が導入され、外国人労働者の受け入れが大幅に拡大された。しかし移民政策の成否は、単なる人数の問題ではなく、いかに社会統合を実現するかにかかっている。\n社会統合の失敗事例として、欧州の一部では移民の集住によるゲットー化、ホスト社会との文化的摩擦、若年移民の失業率の高さといった問題が顕在化している。これらは適切な語学教育・職業訓練・差別禁止法制の整備が伴わない受け入れ拡大が招く帰結である。\n一方、移民がイノベーションと経済成長の担い手となっている事例も多く、シリコンバレーの起業家の相当数が移民一世・二世であることはよく知られた事実である。重要なのは、移民を「問題」として捉える視点ではなく、多様な文化的背景と経験を持つ人材として社会に位置づける視点である。多文化共生社会の実現には、制度的な整備とともに、ホスト社会側の意識改革が不可欠である。', 'article', 'N1', 495, '[]'::jsonb, '{"question":"本文で述べられている社会統合の失敗事例として挙げられていないものはどれか。","options":["移民によるホスト国の犯罪率の上昇","移民の集住によるゲットー化","ホスト社会との文化的摩擦","若年移民の失業率の高さ"],"answer":0}'::jsonb, 118
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='移民政策と社会統合');

-- sort_order 119: 教育格差と機会の平等  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '教育格差と機会の平等', E'「生まれた家庭によって人生が決まる」という現実は、機会の平等を標榜する民主主義社会の根幹を揺るがす問題である。日本においても、親の収入・学歴・居住地域によって子どもの教育達成度が大きく左右されることが、多くの研究によって示されている。大学進学率は親の所得水準と強い正の相関を示しており、教育を通じた社会移動の流動性が低下していることが懸念されている。\n教育格差の背景には複合的な要因がある。私立学校・学習塾・習い事への経済的アクセスの差、文化資本（家庭での会話の質・読書習慣・芸術体験など）の差、そして学校の質の地域差が相互に作用して格差を増幅させる。特に「教育虐待」という概念が示すように、家庭の教育方針が子どもの発達に与える影響は計り知れない。\n格差是正に向けた政策としては、給付型奨学金の拡充・幼児教育の無償化・少人数学級の推進などが取り組まれているが、抜本的な解決には至っていない。重要なのは、支援の重点を就学後ではなく就学前の乳幼児期に置くという知見である。ノーベル経済学賞受賞者ヘックマンの研究は、幼少期への教育投資が最も高い社会的リターンをもたらすことを実証しており、政策の優先順位の再考を促している。', 'article', 'N1', 510, '[]'::jsonb, '{"question":"ヘックマンの研究について本文が述べていることはどれか。","options":["高等教育への投資が最も高い社会的リターンをもたらすことを実証した。","教育格差の主因は文化資本の差異にあることを証明した。","給付型奨学金の拡充が格差是正に最も効果的であることを示した。","幼少期への教育投資が最も高い社会的リターンをもたらすことを実証した。"],"answer":3}'::jsonb, 119
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='教育格差と機会の平等');

-- sort_order 120: ロボット工学と人間の共存  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'ロボット工学と人間の共存', E'産業用ロボットは1960年代の自動車工場への導入以来、製造業の生産性を飛躍的に向上させてきた。21世紀に入り、AIと機械学習の進歩によってロボットは単純な繰り返し作業にとどまらず、視覚認識・自律的な意思決定・人との協働が求められる複雑なタスクもこなせるようになった。こうした「協働ロボット（コボット）」は、人間の作業員と同じ空間で安全に動作するよう設計されており、中小企業や介護・医療分野でも導入が進んでいる。\n介護ロボットの普及は、高齢化社会における介護人材不足の解消に大きな期待を集めている。移乗・入浴・歩行支援などを補助するロボットは介護者の身体的負担を軽減し、要介護者の自立を支える可能性がある。しかし、機械による介護が人間的なつながりや尊厳をどう扱うかという倫理的問いは、技術的解決では答えられない。\nロボットと人間の共存を考える上で重要なのは、ロボットが「仕事を奪う」のではなく「人間がより重要な業務に集中できる環境を作る」という視点の転換である。この転換を実現するには、技術の設計段階から人間中心の哲学を組み込む必要があり、エンジニアだけでなく社会科学者・倫理学者・現場の利用者が開発に関与する参加型設計が求められる。', 'essay', 'N1', 505, '[]'::jsonb, '{"question":"本文で「協働ロボット（コボット）」として説明されているものはどれか。","options":["工場の危険区域で人間の代わりに単純作業を行う産業用ロボット","人間の作業員と同じ空間で安全に動作するよう設計されたロボット","自律的に医療診断を行う医療特化型ロボット","介護施設専用に設計された移乗補助ロボット"],"answer":1}'::jsonb, 120
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='ロボット工学と人間の共存');

-- sort_order 121: 消費社会と環境負荷  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '消費社会と環境負荷', E'現代の消費社会は、大量生産・大量消費・大量廃棄のサイクルの上に成り立っており、その環境負荷は地球の自然回復能力を超えるところまで達している。国際環境NGOのグローバル・フットプリント・ネットワークは、人類が一年間に消費する資源量が地球の再生能力を超える日を「アース・オーバーシュート・デイ」として毎年算出しており、近年この日は年々早まる傾向にある。\nファッション産業は、世界の炭素排出量の約10パーセントを占める環境汚染産業の代表格である。特に年に数十のシーズンを展開する「ウルトラファストファッション」は、低価格で大量の衣料品を流通させ、着用回数の少ないまま廃棄されるという使い捨て文化を助長している。安価な繊維製品は発展途上国での劣悪な労働環境とも密接に結びついており、環境問題と社会問題は切り離せない。\n対抗する動きとして、「循環経済（サーキュラーエコノミー）」のモデルが注目されている。製品の設計段階から廃棄を念頭に置き、資源を循環させ続けることで廃棄物をゼロに近づけるこのアプローチは、線形経済（作って・使って・捨てる）への根本的なオルタナティブとして、EU規制や企業戦略の中心に位置づけられつつある。', 'article', 'N1', 500, '[]'::jsonb, '{"question":"「アース・オーバーシュート・デイ」とは何か、本文から正しく説明しているものはどれか。","options":["世界的な消費削減キャンペーンの統一行動日","地球温暖化の影響が取り返しのつかない段階に達した日として記念される日","人類が一年間に消費する資源量が地球の再生能力を超える日","国際環境機関が毎年発表する最も汚染が深刻な国を発表する日"],"answer":2}'::jsonb, 121
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='消費社会と環境負荷');

-- sort_order 122: 高齢者の孤立と地域コミュニティ  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '高齢者の孤立と地域コミュニティ', E'日本では「孤独死」という言葉が社会問題として広く認識されている。誰にも看取られることなく自宅で亡くなり、長期間発見されないという事態は、単に悲惨な個人の不幸ではなく、地域コミュニティの崩壊と社会的紐帯の希薄化を象徴する現象である。内閣府の調査によれば、60歳以上の一人暮らし高齢者の約30パーセントが、近所の人とほとんど会話しないと回答している。\n高齢者の社会的孤立は、身体的健康にも深刻な影響を及ぼすことが明らかになっている。孤独感と孤立は心臓疾患・認知症・免疫機能低下との相関が示されており、一部の研究では孤立の健康への悪影響が喫煙に匹敵するとも言われる。英国が2018年に「孤独担当大臣」を世界で初めて任命したことは、孤独を個人の問題ではなく公衆衛生の課題として位置づける画期的な政策転換であった。\n地域コミュニティの再建には、既存の町内会・自治会の活性化だけでなく、多世代が交流できる「コミュニティカフェ」や「シェアリングエコノミー」の仕組みを活用した新しいつながりの形成が有効とされる。重要なのは、高齢者を保護の対象としてのみ捉えるのではなく、地域の担い手・知恵の継承者として役割を持てる環境を整えることである。', 'article', 'N1', 505, '[]'::jsonb, '{"question":"英国が2018年に取った行動として本文に述べられているのはどれか。","options":["世界で初めて孤独担当大臣を任命した。","孤独問題に関する初の国際条約に署名した。","高齢者の孤独死を犯罪として取り締まる法律を制定した。","コミュニティカフェの全国展開に公的資金を投入した。"],"answer":0}'::jsonb, 122
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='高齢者の孤立と地域コミュニティ');

-- sort_order 123: 核エネルギーの是非  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '核エネルギーの是非', E'脱炭素社会に向けたエネルギー政策の議論において、原子力発電の評価をめぐる意見は大きく二分されている。支持派は「原子力は発電時にCO2をほとんど排出せず、安定した大規模電力を供給できる唯一の低炭素電源だ」と主張し、気候変動対策の観点から原子力の不可欠性を訴える。一方、反対派は「放射性廃棄物の最終処分問題が未解決のまま、安全性の確保されていないリスクを将来世代に押しつけることは許されない」と批判する。\n2011年の東京電力福島第一原子力発電所事故は、原子力に対する世界的な認識を一変させた。ドイツはこの事故を契機に脱原発方針を加速し、2023年に国内すべての原子炉の運転を停止した。日本でも全国の原発が順次停止されたが、電力逼迫・電気料金の高騰・温室効果ガス増加という事態を受け、2022年以降は原発の再稼働と新増設を容認する方向に政策転換が図られた。\n原子力の評価は純粋に技術的・経済的な問題ではなく、リスクをどう解釈し、誰が費用を負担し、将来世代への責任をどう考えるかという価値判断の問題でもある。したがってこの議論は専門家だけでなく市民が広く参加する民主的プロセスを通じて行われるべきである。', 'essay', 'N1', 510, '[]'::jsonb, '{"question":"2011年の福島原発事故後のドイツの対応として本文が述べていることはどれか。","options":["事故直後に全原発を停止したが、電力不足のため翌年すべてを再稼働した。","日本との共同で新世代の安全な原発開発に着手した。","事故を受けて原発の安全基準を大幅に強化したが、原発は継続使用した。","事故を契機に脱原発方針を加速し、2023年に国内すべての原子炉の運転を停止した。"],"answer":3}'::jsonb, 123
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='核エネルギーの是非');

-- sort_order 124: デザイン思考と問題解決  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'デザイン思考と問題解決', E'デザイン思考とは、デザイナーが製品開発において用いてきた問題解決の方法論を、ビジネス・教育・公共政策など幅広い領域に応用したアプローチである。共感（Empathize）・定義（Define）・発想（Ideate）・プロトタイプ（Prototype）・テスト（Test）という5段階のプロセスを通じて、ユーザーの潜在的なニーズを深く理解し、革新的な解決策を導き出すことを目指す。\nデザイン思考の核心は「人間中心」という哲学にある。従来の問題解決が既存のデータや技術的制約から出発するのに対し、デザイン思考は観察・インタビュー・共感的理解を通じてユーザーの経験や感情を起点とする。この発想の転換が、市場調査では見えてこない潜在的ニーズの発見につながることがある。\nただしデザイン思考には批判もある。プロセスが定型化されることで本来の創造性が失われるという指摘や、複雑な社会問題に対して過度に楽観的なソリューション思考を持ち込むことへの懸念も示されている。また、「共感」という概念が表面的なユーザー観察にとどまり、権力構造や制度的矛盾の分析を回避する「脱政治化」の手法として機能する危険性も指摘されている。デザイン思考は万能の解決策ではなく、他の分析手法と組み合わせて使うことで真価を発揮するものである。', 'essay', 'N1', 505, '[]'::jsonb, '{"question":"デザイン思考への批判として本文に述べられていないものはどれか。","options":["プロセスが定型化されることで創造性が失われるという指摘","複雑な社会問題への過度に楽観的なソリューション思考への懸念","デザイン思考はビジネスにのみ有効で教育や政策には応用できないという批判","共感概念が権力構造の分析を回避する脱政治化の手法として機能する危険性"],"answer":2}'::jsonb, 124
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='デザイン思考と問題解決');

-- sort_order 125: 感染症対策とプライバシー  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '感染症対策とプライバシー', E'新型コロナウイルス感染症のパンデミックは、感染症対策と個人のプライバシー・自由との間に生じる緊張関係を、世界規模で顕在化させた。接触確認アプリ・健康状態の自己申告・ワクチン接種証明の提示要求など、感染拡大を抑制するための措置は、個人の行動情報を国家・企業が収集・管理する仕組みを急速に拡大させた。\n特に問題とされたのが、緊急措置として導入された監視技術や個人情報収集の仕組みが、パンデミック終息後も恒常的なインフラとして残存するリスクである。歴史的に見て、危機時に拡大した国家の権限が平時に縮小されることは少なく、「緊急の例外」が「新たな常態」へと転化するパターンが繰り返されてきた。\n一方、デジタル技術を活用した感染症対策の有効性も否定できない。台湾・韓国・シンガポールなどでは、データ活用と迅速なトレーシングにより感染拡大を効果的に抑制した事例がある。重要なのは、収集するデータの範囲・利用目的・保存期間を厳格に限定し、独立した監査機関による監視と、パンデミック終息後の確実なデータ削除を法的に義務づける仕組みを、危機の発生前に整備しておくことである。', 'article', 'N1', 500, '[]'::jsonb, '{"question":"本文で筆者が最も重要だと述べていることはどれか。","options":["危機時の監視技術の恒常化を防ぐために、データの範囲・目的・保存期間を限定する法的仕組みを事前に整備すべきだ。","感染症対策においては個人のプライバシーより公衆衛生を優先すべきだ。","デジタル技術による感染症対策は有効性が証明されていないため使用を控えるべきだ。","接触確認アプリは任意参加ではなく義務化することで効果を高めるべきだ。"],"answer":0}'::jsonb, 125
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='感染症対策とプライバシー');

-- sort_order 126: 林業の衰退と森林保全  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '林業の衰退と森林保全', E'日本の国土の約67パーセントを森林が占めており、これは先進国の中でもフィンランド・スウェーデンに次ぐ高い森林率である。しかしその豊かな森林の多くが、今日では適切な管理がなされないまま放置され、生態系サービスの低下と山地災害リスクの増大を招いている。\n戦後の高度経済成長期に植林された人工林（主にスギ・ヒノキ）が伐期を迎えているにもかかわらず、国産材の価格が輸入材との競合により低迷し、林業経営が成立しないという構造的問題がある。林業従事者は過去50年で約80パーセント減少し、山林の担い手不足は深刻である。間伐が行われないまま密植状態が続く人工林は、林床への光が届かず下草が育たないため、大雨の際に表土が流出し土砂崩れのリスクが高まる。\n近年、国産材の利用促進策として、CLT（直交集成板）など新技術を活用した木材の建築利用拡大や、木質バイオマスによる発電・熱利用の普及が図られている。また、企業がカーボンオフセットとして森林整備に投資する仕組みも広がっている。林業の再生は経済政策であると同時に、防災・水源涵養・生物多様性保全という公益的機能の維持という観点からも、社会全体で取り組むべき課題である。', 'report', 'N1', 510, '[]'::jsonb, '{"question":"本文で述べられている日本の人工林の問題として正しいのはどれか。","options":["戦後に植林されたスギ・ヒノキが病虫害により大規模に枯死している。","輸入材との競合により国産材の品質が低下し、建築利用が困難になっている。","人工林の面積が急速に縮小し、国土の森林率が低下している。","間伐不足により密植状態が続き、大雨時の表土流出・土砂崩れリスクが高まっている。"],"answer":3}'::jsonb, 126
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='林業の衰退と森林保全');

-- sort_order 127: 人工知能と創造性  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '人工知能と創造性', E'「創造性は人間に固有の能力だ」という命題は長らく自明のものとして受け入れられてきたが、生成AIの急速な発展がこの前提を根底から問い直している。GPTシリーズに代表される大規模言語モデルは小説・詩・脚本を生成し、画像生成AIは美術賞を受賞し、作曲AIはプロのミュージシャンと共同制作を行うまでに至っている。\n支持者は「AIは創造性を持っていない。ただ既存データのパターンを組み合わせているに過ぎない」と主張する。この見方によれば、真の創造性とは意図・感情・経験に基づく「何かを伝えたい」という動機から生まれるものであり、その動機を持たないAIの出力は創造的に見えても本質的には模倣に過ぎない。\n一方、「人間の創造性もまた、先人の作品・文化・経験という入力データのパターン処理ではないか」という反論もある。人間の脳もニューラルネットワークである以上、AIと人間の創造性の差異は種類の差ではなく程度の差に過ぎないという議論は一定の説得力を持つ。重要なのは、AIの創造性が人間のそれと同じかどうかではなく、AIの登場によってアーティスト・作家・作曲家がどう仕事の意味を再定義するかという実践的な問いである。', 'essay', 'N1', 505, '[]'::jsonb, '{"question":"本文でAIの創造性を否定する立場の主張として述べられているのはどれか。","options":["AIは人間と同じニューラルネットワーク構造を持つため、創造性も同様だ。","AIは既存データのパターン処理に過ぎず、伝えたい動機がないため真の創造性ではない。","AIの創造的出力は品質が低く、人間のアーティストと競争できるレベルにない。","AI生成物は著作権を持てないため、創造性の産物とは認められない。"],"answer":1}'::jsonb, 127
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='人工知能と創造性');

-- sort_order 128: 格差社会と貧困の連鎖  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '格差社会と貧困の連鎖', E'経済格差の拡大は、20世紀後半から先進国・途上国を問わず世界的に進行してきた。「ピケティの法則」として知られるトマ・ピケティの研究は、資本収益率が経済成長率を上回る傾向があるため、資産を持つ者はさらに豊かになり、持たない者との差が拡大し続けるという構造的メカニズムを明らかにした。\nより深刻な問題は、格差が固定化し世代を超えて継承される「貧困の連鎖」である。経済的に不利な家庭に生まれた子どもは、教育機会の制限・栄養状態の不良・ストレスの多い環境への慢性的な曝露などにより、認知的・社会情緒的発達において不利を抱える傾向がある。こうして生まれた不平等は、能力の差ではなく環境の差に起因するものであるため、実力主義（メリトクラシー）の枠組みでは是正できない。\n格差是正のための政策手段としては、累進課税の強化・富裕税の導入・相続税率の引き上げ・社会保障の充実・公教育への投資拡大などが論じられている。しかし格差の根本にある「機会の不平等」に取り組むには、制度設計だけでなく、成功を個人の努力だけに帰する「自己責任論」の文化的再検討が不可欠である。', 'article', 'N1', 500, '[]'::jsonb, '{"question":"「ピケティの法則」として本文が説明していることはどれか。","options":["貧困家庭の子どもは教育機会が制限されるため、貧困が世代を超えて継承される。","実力主義の社会では努力次第で格差を解消できる。","資本収益率が経済成長率を上回る傾向があるため、資産を持つ者はさらに豊かになり格差が拡大する。","累進課税の強化により資本収益の不均等分配を是正できる。"],"answer":2}'::jsonb, 128
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='格差社会と貧困の連鎖');

-- sort_order 129: 脳科学と学習効率  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '脳科学と学習効率', E'神経科学の知見は、効率的な学習方法についての従来の常識を覆しつつある。長時間の集中学習（マスしング）よりも、学習セッションを時間的に分散させる「分散学習（スペーシング効果）」のほうが長期的な記憶定着に優れていることは、100年以上前から実験的に確認されていたにもかかわらず、教育現場での実践は遅れている。\n同様に、解答を確認する前に自ら答えを思い出そうとする「検索練習（リトリーバル・プラクティス）」は、繰り返し読むだけの受動的学習と比較して記憶の強化に劇的に優れることが示されている。試験を嫌うこと勿れ。試験という行為自体が、最も効果的な学習ツールの一つである。\nまた、睡眠が記憶の定着に果たす役割も近年の研究で明確になってきた。学習した内容は睡眠中にシナプスの再編成が行われることで長期記憶へと転換されるため、徹夜学習は一時的な記憶保持には機能しても、深い理解と長期保持には逆効果となる。さらに有酸素運動が海馬での神経新生を促し、学習能力と記憶力を向上させることも確認されており、「体を動かすことは脳のためになる」という知見は、教育政策にも取り入れられるべきであろう。', 'article', 'N1', 500, '[]'::jsonb, '{"question":"本文で「検索練習（リトリーバル・プラクティス）」として説明されているのはどれか。","options":["解答確認前に自ら答えを思い出そうとする学習法","インターネットで関連情報を検索しながら学習する方法","学習後に類似した問題集を繰り返し解く方法","分散学習セッションの合間に学習内容を声に出して確認する方法"],"answer":0}'::jsonb, 129
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='脳科学と学習効率');

-- sort_order 130: 観光業と地域経済  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '観光業と地域経済', E'インバウンド観光（訪日外国人旅行）は、2010年代を通じて日本の重要な成長産業として急速に発展した。2019年には訪日外客数が3188万人、消費額が4兆8千億円に達し、観光を地方経済活性化の切り札として位置づける「観光立国」政策の追い風となった。しかし2020年のコロナ禍による国際旅行の激減は、観光依存度の高い地域経済の脆弱性を露わにした。\nコロナ禍が収束した2022年以降、訪日客数は急速に回復し、2024年には過去最高水準に達したが、同時に「オーバーツーリズム（観光公害）」という新たな問題が顕在化した。京都・鎌倉・富士山周辺などの人気観光地では、外国人観光客の急増による交通渋滞・騒音・ゴミ問題・マナー違反が地域住民の生活を圧迫し、観光業の利益と住民の生活環境悪化が鋭く対立する事態となっている。\n持続可能な観光（サステナブルツーリズム）の実現には、観光客数の量的拡大から質的向上への転換が不可欠である。混雑する観光地から地方の穴場スポットへの分散を促す「デスティネーション・マネジメント」、入場料・混雑税の導入による需要調整、地域住民が観光業の利益を公平に享受できるガバナンスの整備が求められている。', 'report', 'N1', 505, '[]'::jsonb, '{"question":"本文でオーバーツーリズムとして挙げられている問題はどれか。","options":["訪日外国人数が少なすぎて、地方の観光業が経営困難に陥っていること","外国人観光客向けのサービス業で人手不足が深刻化していること","地方の観光地が観光客を誘致できず、観光収入が都市部に集中していること","観光客の急増による交通渋滞・騒音・ゴミ問題が地域住民の生活を圧迫していること"],"answer":3}'::jsonb, 130
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='観光業と地域経済');

-- sort_order 131: ダイバーシティと職場環境  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'ダイバーシティと職場環境', E'ダイバーシティ（多様性）とインクルージョン（包摂）を推進する経営戦略は、倫理的要請であると同時に、ビジネス上の合理的選択としても広く認識されるようになった。マッキンゼーなど複数のコンサルティング会社の調査は、性別・人種・民族の多様性が高い企業は財務パフォーマンスが優れる傾向にあることを示しており、同質的な組織に比べて革新的なアイデアが生まれやすいとされる。\nしかし日本企業においては、ダイバーシティ推進は依然として緒についたばかりである。管理職に占める女性比率は主要先進国の中で最低水準にとどまり、障害者雇用率も法定雇用率を下回る企業が後を絶たない。外国人労働者の幹部登用も例外的な存在に過ぎない。\n真のインクルージョンとは、単に多様な属性の人材を採用するだけでなく、すべての従業員が自らの能力を最大限に発揮できる組織文化と制度を整えることを意味する。マイノリティのメンバーに「主流文化に同化する」ことを暗黙のうちに求めるような環境では、表面的な多様性は達成されても包摂は実現しない。「心理的安全性」の確保、無意識の偏見（アンコンシャス・バイアス）への教育、柔軟な働き方の制度化が、インクルーシブな職場の基盤となる。', 'essay', 'N1', 505, '[]'::jsonb, '{"question":"本文で「真のインクルージョン」として筆者が述べていることはどれか。","options":["多様な属性の人材を法定割合以上に採用すること","マイノリティのメンバーが主流文化に適応するための教育を実施すること","すべての従業員が能力を最大限発揮できる組織文化と制度を整えること","外国人幹部の比率を主要先進国と同水準に引き上げること"],"answer":2}'::jsonb, 131
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='ダイバーシティと職場環境');

-- sort_order 132: 食文化の変容とグローバル化  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '食文化の変容とグローバル化', E'食は文化の最も根源的な表現の一つであり、何を食べ、いかに食べるかはその社会の価値観・宗教・歴史・気候を反映している。しかしグローバル化の進展とともに、食文化は急速な変容を遂げており、世界各地でファストフード・加工食品・外来の食材が在来の食習慣に取って代わる「食の西洋化・均質化」が進んでいる。\n日本においても、戦後の高度経済成長期から食の洋風化が急速に進み、米の消費量が50年で半減する一方でパン・肉類・乳製品の摂取が増加した。伝統的な「一汁三菜」を基本とする日本食の形態は、ユネスコ無形文化遺産に「和食」として登録されているものの、日常の食卓から急速に遠のいている。\n逆説的なことに、グローバル化は食文化の均質化を促す一方で、各国・各地域の食文化への関心と評価を高める効果も持っている。世界中で日本食レストランが急増し、日本の食材・調理法・食器が輸出され、「ガストロノミーツーリズム（食を目的とした旅行）」が成長産業となっているのは、均質化への反動として食の多様性が価値を持ち始めた証左と言えよう。食の伝統は守るものではなく、異文化との対話を通じて絶えず再創造されていくものであるとも言える。', 'essay', 'N1', 510, '[]'::jsonb, '{"question":"本文でグローバル化と食文化の関係について述べられていることとして正しいのはどれか。","options":["グローバル化は食文化の均質化のみを招き、各国の伝統食は消滅の危機にある。","グローバル化は食文化の均質化を促す一方で、各地域の食文化への関心を高める効果も持っている。","食の伝統は外来文化との接触から厳格に保護されるべきだと筆者は主張している。","日本食のユネスコ無形文化遺産登録により、日常の食卓での和食回帰が進んでいる。"],"answer":1}'::jsonb, 132
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='食文化の変容とグローバル化');

-- sort_order 133: 自動運転技術の普及  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '自動運転技術の普及', E'自動運転技術は、交通事故の大幅削減・高齢者や障害者の移動の自由確保・渋滞緩和・物流の効率化など、社会に多大な恩恵をもたらすと期待されている。SAE（米国自動車技術会）による自動化レベルの定義では、レベル0（運転自動化なし）からレベル5（完全自動化）まで6段階があり、現在市場で普及しているのは主にレベル2（部分的運転支援）の機能である。\nレベル4（特定条件下での完全自動化）以上の車両の公道走行は、一部の限定された地域・条件下で試験・実用化が始まっているが、技術的・法的・倫理的課題が山積している。技術面では、悪天候・複雑な市街地環境・予測不能な歩行者行動への対応が依然として難題とされる。法的側面では、自動運転中に事故が発生した場合の責任の帰属（メーカー・所有者・乗客・道路管理者のいずれが責任を負うか）という問題が未整備のまま残っている。\n倫理面では、事故が不可避な状況で誰の安全を優先するかという「トロッコ問題」的ジレンマをアルゴリズムがいかに解くかという問いが注目を集めている。完全自動運転の普及には、技術の成熟だけでなく、社会全体でこれらの価値判断について合意を形成するプロセスが不可欠である。', 'article', 'N1', 510, '[]'::jsonb, '{"question":"本文で述べられている自動運転の法的課題はどれか。","options":["自動運転技術に関する特許権をめぐる企業間の争いが続いていること","自動運転の試験走行を承認する行政手続きが複雑すぎること","自動運転車の製造・販売に関する国際統一基準がないこと","自動運転中の事故発生時に誰が責任を負うかが未整備のまま残っていること"],"answer":3}'::jsonb, 133
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='自動運転技術の普及');

-- sort_order 134: 心理的安全性と組織文化  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '心理的安全性と組織文化', E'心理的安全性（サイコロジカル・セーフティ）とは、チームメンバーが対人関係上のリスクを恐れることなく、率直な意見・疑問・懸念・失敗を表明できると感じる状態を指す。この概念は組織心理学者エイミー・エドモンドソンが1990年代に提唱し、その後グーグルが行った「プロジェクト・アリストテレス」でハイパフォーマンスチームの最も重要な特性として同定されたことで、ビジネス界でも広く注目されるようになった。\n心理的安全性が高い職場では、メンバーが失敗を恐れずに新しいアイデアを試み、問題が生じた際に早期に報告し、互いの知識を率直に共有するため、イノベーションと学習の速度が高まる。一方、心理的安全性が低い環境では、「言うと叩かれる」という恐怖から誰も問題を指摘せず、組織の失敗が見えにくくなる。航空機事故の調査では、機長への過度な遠慮から副操縦士が危険情報を報告しなかったことが原因の一端となった事例が複数記録されている。\n心理的安全性の高い組織文化を醸成するには、リーダー自身が積極的に「わからない」「失敗した」と表明し、部下の発言を批判せずに受け止めるモデル行動が不可欠である。ただし心理的安全性は「何でも許される」という意味ではなく、高い基準と心理的安全性を両立させてこそ、真の学習する組織が生まれる。', 'article', 'N1', 510, '[]'::jsonb, '{"question":"グーグルの「プロジェクト・アリストテレス」について本文が述べていることはどれか。","options":["ハイパフォーマンスチームの最も重要な特性として心理的安全性を同定した。","グーグルが開発した人工知能プロジェクトで、チームの生産性管理に活用されている。","心理的安全性よりも高い成果基準がチームパフォーマンスに最も重要だと結論づけた。","エイミー・エドモンドソンがグーグルとの共同研究で提唱した組織変革手法だ。"],"answer":0}'::jsonb, 134
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='心理的安全性と組織文化');

-- sort_order 135: デジタルデトックスと現代人の生活  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'デジタルデトックスと現代人の生活', E'スマートフォンの普及によって、現代人は一日に平均4〜5時間以上をスクリーンの前で過ごすといわれる。通知音が鳴るたびに画面を確認する行動は、単なる習慣を超えた条件反射と化しており、デジタル機器への依存は薬物依存と同様のドーパミン報酬回路を活用するよう設計されているという指摘もある。\nこうした状況への反動として生まれたのが「デジタルデトックス」の概念である。一定期間スマートフォン・SNS・電子メールなどのデジタルツールから意図的に離れることで、精神的な余裕を取り戻し、リアルな人間関係や自然体験を再発見しようという試みである。デジタルデトックスの実践者は、集中力の向上・睡眠の質の改善・不安感の低減・対面コミュニケーションの充実を実感する者が多いと報告されている。\nただし、デジタルデトックスを「デジタル機器はすべて悪である」という極論と混同すべきではない。問題はデジタル機器そのものではなく、それとの関係が能動的な制御から受動的な依存へと転落することにある。「意図的な使用（インテンショナル・ユース）」すなわち何のために・どのくらい・どのように使うかを自覚的に選択する能力こそが、デジタル時代の健全な生活を支える核心的スキルである。', 'essay', 'N1', 505, '[]'::jsonb, '{"question":"本文で筆者が最も重要だと述べているのはどれか。","options":["スマートフォンの通知をすべてオフにして集中できる環境を作ること","SNSへのアクセスを一日1時間に制限する法的規制を導入すること","デジタル機器の使用を意図的に制御する「インテンショナル・ユース」の能力","デジタル機器から完全に離れるデジタルデトックスを定期的に実践すること"],"answer":2}'::jsonb, 135
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='デジタルデトックスと現代人の生活');
